WITH session_totals AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_pages, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.browser, sessions.started_at, session_totals.unique_pages, session_totals.stddev_duration_sec FROM sessions LEFT JOIN session_totals ON sessions.id = session_totals.session_id WHERE session_totals.stddev_duration_sec > 44;
